{
  "name": "weekly_review_report",
  "request_shape": "Weekly review: list my to-dos due this week, my meetings this week, and the mail I have not answered yet, as one report.",
  "inputs": ["to_do_list", "meeting_list", "mail_list"],
  "steps": [
    {
      "id": "step_1",
      "kind": "list",
      "source": "todos",
      "filter": "due_date_within_week"
    },
    {
      "id": "step_2",
      "kind": "list",
      "source": "calendar",
      "filter": "events_within_week"
    },
    {
      "id": "step_3",
      "kind": "list",
      "source": "mail",
      "filter": "status_unanswered"
    },
    {
      "id": "step_4",
      "kind": "batch",
      "size": 10
    },
    {
      "id": "step_5",
      "kind": "loop_over_items",
      "over": "step_4",
      "steps": [
        {
          "id": "step_6",
          "kind": "classify",
          "enum": ["urgent", "normal", "low_priority"],
          "question": "What is the priority of this item?"
        }
      ]
    },
    {
      "id": "step_7",
      "kind": "write",
      "instruction": "Combine the to-dos, meetings, and unanswered mail into a single weekly review report, including priority classifications.",
      "max_words": 500
    },
    {
      "id": "step_8",
      "kind": "check_coverage",
      "rule": "every input item from step_1, step_2, and step_3 must appear in the final output exactly once"
    }
  ],
  "output": "weekly_review_report"
}
